          "answer": 0,
          "explanation": "int(3.14)是把实数3.14强制转换成整数类型的写法，转换时直接去掉小数部分，只保留整数部分3。C++中从实数到整数的转换是直接截断而不是四舍五入，所以int(3.14)的值确实是3，判断正确。",
