          "question": "执行下面C++代码可以判断一个6位正整数 N 的高3位和低3位的差是否是314的倍数。例如 628314 就符合要求。横线处应该填入（　　）。\n\ncin >> N;\nif (___________________________)\n    cout << N << \"符合条件\" << endl;",
