          "explanation": "本题主要考察C++基本运算中的逻辑运算；选项A 条件1 是a==0，条件2 是b==0，两个条件之间用逻辑与&&，两个条件都满足，整个条件就满足，符合a 等于0 且b 等于0；选项B 是先判断a 和b 是否相等，若相等表达式a==b 的值为1，若不相等a==b的值为0，再判断表达式a==b 的值是否等于0，只有a 和b 不相等时，整个表达式成立；选项C 条件1 是!a，a 为0 时，!a 为1，条件成立，条件2 是!b，b 为0 时，!b为1，条件成立，两个条件之间是逻辑与&&关系，两个条件都满足，整个条件就满足，符合a 等于0 且b 等于0；选项D 中a==0 条件满足为1，b==0 条件满足也为1，两个都满足相加结果为2，两个条件有任意不满足则相加结果可能为0 或1。因此，判断相加结果是否等于2，符合a 等于0 且b 等于0；所以本题正确答案为B。",
