          "explanation": "本题属于考察C++的基本运算中的逻辑运算；A 选项会先判断a 和b 是否相等，只有a 和b 不相等，a==b 表达式的值才为0，所以A 选项判断是a 不等于b。B 选项中，若！(a || b)为真，则(a||b)结果为0，若a 和b 有任意一个不为0，(a||b)的值都为1，所以当a 等于0 且b 等于0 时，(a || b)的结果才为0，!(a||b)的值才为1。C 选项判断的是a+b 的和是否为0，当a 和b 互为相反数时条件即可成立，a 和b不一定为0。D 选项判断的时表达式(a==0)和表达式(b==0)的和，只要a 和b 中有任意一个为0，最终表达式的值都大于0，即为真。所以本题正确答案为B。",
