          "kp": "kp1_07",
          "type": "coding",
          "difficulty": 1,
          "question": "【问题描述】\n小杨最近学习了开尔文温度、摄氏温度和华氏温度的转换。令符号K表示开尔文温度，符号C表示摄氏温度，符号F表示华氏温度，这三者的转换公式如下：K = C + 273.15，F = 32 + 1.8 × C。\n现在小杨想编写一个程序计算某一开尔文温度对应的摄氏温度和华氏温度，你能帮帮他吗？\n\n【输入描述】\n一行，一个实数K，表示开尔文温度。\n\n【输出描述】\n一行，若输入开尔文温度对应的华氏温度高于212，输出 Temperature is too high! ；否则，输出两个空格分隔的实数C和F，分别表示摄氏温度和华氏温度，保留两位小数。\n\n【样例输入 1】\n412.00\n\n【样例输出 1】\nTemperature is too high!\n\n【样例输入 2】\n173.56\n\n【样例输出 2】\n-99.59 -147.26",
          "options": [],
          "answer": null,
          "explanation": "思路：C=K-273.15，F=32+1.8×C。先算出F，若F>212则输出提示；否则用printf保留两位小数输出C和F。注意浮点运算和输出格式控制。",
          "source": "GESP2024-12",
          "isJudge": false,
          "answerText": "#include <iostream>\n#include <cstdio>\nusing namespace std;\nint main(){\n    double K; cin>>K;               // 读入开尔文温度K\n    double C=K-273.15;              // 用公式K=C+273.15，算出摄氏温度C\n    double F=32+1.8*C;              // 用公式F=32+1.8×C，算出华氏温度F\n    if(F>212){                      // 如果华氏温度超过212\n        cout<<\"Temperature is too high!\"<<endl;  // 输出提示：温度太高\n    }else{                          // 否则\n        printf(\"%.2f %.2f\\n\",C,F); // 输出摄氏温度和华氏温度，保留2位小数\n    }\n    return 0;                       // 程序正常结束\n}",
