          "type": "coding",
          "difficulty": 1,
          "question": "【问题描述】\n图书馆里有n本书，不幸的是，还混入了一只老鼠，老鼠每x小时能啃光一本书，假设老鼠在啃光一本书之前，不会啃另一本。请问y小时后图书馆里还剩下多少本完整的书。\n\n【输入描述】\n三行，第一行一个正整数n，表示图书馆里书的数量；第二行，一个正整数x，表示老鼠啃光一本书需要的时间；第三行，一个正整数y，表示经过的总时间；输入数据保证y小时后至少会剩下一本完整的书。\n\n【输出描述】\n一行，一个整数，表示y小时后图书馆里还剩下多少本完整的书。\n\n【数据范围】\n对于所有测试点，保证n、x、y均不超过1000，保证y小时后至少会剩下一本完整的书。\n\n【样例输入 1】\n10\n2\n3\n\n【样例输出 1】\n8\n\n【样例输入 2】\n5\n2\n4\n\n【样例输出 2】\n3",
          "options": [],
          "answer": null,
          "explanation": "思路：老鼠y小时最多能啃完 y÷x 本（整除），因为啃完一本才开始啃下一本，所以实际啃坏 y÷x 本，剩下的完整书数为 n - y÷x。",
          "source": "GESP2025-03",
          "isJudge": false,
          "answerText": "#include <iostream>\nusing namespace std;\nint main(){\n    int n,x,y;                      // 定义：书的数量n、啃光一本书要x小时、经过y小时\n    cin>>n>>x>>y;                   // 读入这3个数\n    int eaten=(y+x-1)/x;            // 用“向上取整”的除法算出y小时里啃光了几本书\n    cout<<n-eaten<<endl;            // 用总书数减去被啃光的，就是剩下的完整书\n    return 0;                       // 程序正常结束\n}",
          "starterCode": null,
