          "kp": "kp1_07",
          "type": "coding",
          "difficulty": 1,
          "question": "【问题描述】\n四舍五入是一种常见的近似计算方法。现在，给定n个整数，你需要将每个整数四舍五入到最接近的整十数。例如，43四舍五入后为40，58四舍五入后为60。\n\n【输入描述】\n共n+1行，第一行一个整数n，表示接下来输入的整数个数。接下来n行，每行一个整数x，表示需要四舍五入的整数。\n\n【输出描述】\nn行，每行一个整数，表示每个整数四舍五入后的结果。\n\n【数据范围】\n对于所有测试点，保证 1 ≤ n ≤ 100，1 ≤ x ≤ 10000。\n\n【样例输入 1】\n5\n43\n58\n25\n67\n90\n\n【样例输出 1】\n40\n60\n30\n70\n90",
          "options": [],
          "answer": null,
          "explanation": "思路：对x四舍五入到整十，看x%10是否大于等于5：若>=5则向上补到整十，否则向下舍去个位。用循环处理n个输入并逐个输出。",
          "source": "GESP2025-03",
          "isJudge": false,
          "answerText": "#include <iostream>\nusing namespace std;\nint main(){\n    int n; cin>>n;                  // 读入一共有几个数\n    while(n--){                     // 每个数都处理一遍，处理一个就少一个\n        int x; cin>>x;              // 读入要四舍五入的数x\n        cout<<(x+5)/10*10<<endl;    // 先加5再除以10再乘10，得到四舍五入到整十的数\n    }\n    return 0;                       // 程序正常结束\n}",
