          "question": "以下C++代码可以找出百位、十位和个位满足特定条件的三位数，横线处应该填入的是（   ）\n\nint count = 0;\nfor (int i = 100; i <= 999; i++) {\n    int a = i / 100;\n    _________________________\n    int c = i % 10;\n    if (a * a + b * b == c * c) {\n        count++;\n    }\n}",
