          "difficulty": 1,
          "question": "下面C++代码执行后的输出是（　　）。\n\nint i, tnt = 1;\nfor (i = 0; i < 5; i++)\n    tnt *= i;\nprintf(\"%2d%2d\\n\", tnt, i);",
