          "difficulty": 1,
          "question": "下面C++代码的相关说法，正确的是（　　）。\n\nint i;\nfor (i = 1; i < 10; i++){\n    if (i % 2 == 0){\n        continue;       // L1\n    }\n    else\n        cout << i << \"#\";\n}\ncout << i << \"END\";",
