          "type": "coding",
          "difficulty": 1,
          "question": "【问题描述】\n小杨需要从 1 到 N 报数。在报数过程中，小杨希望跳过 M 的倍数。例如，如果 N=5，M=2，那么小杨就需要依次报出 1、3、5。现在，请你依次输出小杨报的数。\n\n【输入描述】\n输入 2 行，第一行一个整数 N（1≤N≤1000）；第二行一个整数 M（2≤M≤100）。\n\n【输出描述】\n输出若干行，依次表示小杨报的数。\n\n【数据范围】\n1 ≤ N ≤ 1000\n2 ≤ M ≤ 100\n\n【样例输入 1】\n5\n2\n\n【样例输出 1】\n1\n3\n5\n\n【样例输入 2】\n10\n3\n\n【样例输出 2】\n1\n2\n4\n5\n7\n8\n10",
          "options": null,
          "answer": null,
          "explanation": "思路：for循环让i从1到N，若i%M不等于0则输出i，即跳过所有M的倍数，其余正常输出，每行一个数。",
          "source": "GESP2023-12",
          "isJudge": false,
          "answerText": "#include <stdio.h>\nint main(int argc, char **argv)\n{\n    int n, m, i;                    // 定义：从1报到n，跳过m的倍数\n    scanf(\"%d%d\", &n, &m);          // 读入n和m\n    for(i=1; i<=n; i++)             // 从1开始一直报到n\n    {\n        if(i%m!=0) printf(\"%d\\n\", i);  // 如果i不是m的倍数，就把i报出来\n    }\n    return 0;                       // 程序正常结束\n}",
