          "question": "【问题描述】\n小A最近刚刚学习了因数的概念，具体来说，如果一个正整数a可以被另一个正整数b整除，那么我们就说b是a的因数。请你帮忙写一个程序，从小到大输出正整数a的所有因数。\n\n【输入描述】\n输入一行一个正整数a。保证 1≤a≤1000。\n\n【输出描述】\n输出若干行，为a的所有约数，从小到大排列。\n\n【数据范围】\n1 ≤ a ≤ 1000\n\n【样例输入 1】\n1\n\n【样例输出 1】\n1\n\n【样例输入 2】\n6\n\n【样例输出 2】\n1\n2\n3\n6\n\n【样例输入 3】\n10\n\n【样例输出 3】\n1\n2\n5\n10",
