          "type": "coding",
          "difficulty": 1,
          "question": "【问题描述】\n小明刚刚学习了如何计算长方形面积。他发现，如果一个长方形的长和宽都是整数，它的面积一定也是整数。现在，小明想知道如果给定长方形的面积，有多少种可能的长方形，满足长和宽都是整数？\n如果两个长方形的长相等、宽也相等，则认为是同一种长方形。约定长方形的长大于等于宽。正方形是长方形的特例，即长方形的长和宽可以相等。\n\n【输入描述】\n输入一行，包含一个整数A，表示长方形的面积。约定2 ≤ A ≤ 1000。\n\n【输出描述】\n输出一行，包含一个整数C，表示有C种可能的长方形。\n\n【数据范围】\n2 ≤ A ≤ 1000\n\n【样例输入 1】\n4\n\n【样例输出 1】\n2\n\n【样例输入 2】\n6\n\n【样例输出 2】\n2",
          "options": [],
          "answer": null,
          "explanation": "思路：从1到A枚举长L，如果A能被L整除且宽W=A÷L不大于L，则计数加1。例如面积4可分成1×4、2×2共2种，面积6可分成1×6、2×3共2种，输出计数C。",
          "source": "GESP2023-03",
          "isJudge": false,
          "answerText": "#include <iostream>\nusing namespace std;\nint main(){\n    int A; cin>>A;                  // 读入长方形的面积A\n    int cnt=0;                      // cnt记录有多少种长方形，一开始是0\n    for(int i=1;i*i<=A;i++){        // 只需要试到根号A，因为约定长大于等于宽\n        if(A%i==0) cnt++;           // 如果i能整除A，就找到一种长宽组合\n    }\n    cout<<cnt<<endl;                // 输出方案数\n    return 0;                       // 程序正常结束\n}",
